/* Avelora Online client. Server validates every gameplay action. */
'use strict';
const $=id=>document.getElementById(id);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const pretty=s=>String(s||'').replaceAll('-',' ').replace(/\b\w/g,c=>c.toUpperCase());
const sign=n=>(n>=0?'+':'')+n;
const clamp=(n,a,b)=>Math.min(b,Math.max(a,n));
const types='normal fire water electric grass ice fighting poison ground flying psychic bug rock ghost dragon dark steel fairy'.split(' ');
const weather=['none','sun','rain','sand','snow'], terrain=['none','electric','grassy','misty','psychic'];
const preferredVersions=['scarlet-violet','legends-z-a','sword-shield','brilliant-diamond-and-shining-pearl','legends-arceus','ultra-sun-ultra-moon','sun-moon','omega-ruby-alpha-sapphire','x-y','black-2-white-2','black-white','platinum','diamond-pearl','emerald','firered-leafgreen'];
let state=null,offline=null,selected=null,source=null,es=null,refreshBusy=false;
let ui={tab:'overview',battleMove:0,battleTarget:null,setupAllies:[],setupEnemies:[],editor:null,dexQuery:'',level:5,owner:'',nickname:'',forceShiny:false,teraEnabled:false,megaEnabled:false,teraType:'normal',legendAC:false,bond:0,selectedAbility:'',searchBusy:false,dexError:'',megaForms:[],mobile:false};
let dexNames=[],dexIndexLoading=false,dexIndexError='',dexIndexReady=false;
function dexNormalize(s){return String(s||'').toLowerCase().normalize('NFKD').replace(/[^a-z0-9]/g,'');}
function editDistance(a,b){let prev=Array.from({length:b.length+1},(_,i)=>i);for(let i=1;i<=a.length;i++){const row=[i];for(let j=1;j<=b.length;j++)row[j]=Math.min(row[j-1]+1,prev[j]+1,prev[j-1]+(a[i-1]===b[j-1]?0:1));prev=row;}return prev[b.length];}
function dexMatches(q){q=dexNormalize(q);if(!q||/^\d+$/.test(q))return [];const maxDistance=q.length<4?1:q.length<7?2:3;return dexNames.map(name=>{const n=dexNormalize(name);let score=n===q?-2:n.startsWith(q)?0:n.includes(q)?1:2+Math.min(editDistance(q,n),editDistance(q,n.slice(0,q.length+2)));return {name,score};}).filter(x=>x.score<=1||x.score<=maxDistance+2).sort((a,b)=>a.score-b.score||a.name.length-b.name.length||a.name.localeCompare(b.name)).slice(0,8);}
async function loadDexIndex(){if(dexIndexReady||dexIndexLoading)return;dexIndexLoading=true;dexIndexError='';updateDexSuggestions();try{const response=await fetch('https://pokeapi.co/api/v2/pokemon?limit=10000&offset=0');if(!response.ok)throw new Error('Pokédex search unavailable');const json=await response.json();dexNames=[...new Set((json.results||[]).map(x=>x.name))];dexIndexReady=true;}catch(e){dexIndexError='Full Pokédex suggestions unavailable; exact-name search and offline picks still work.';try{let d=await ensureOffline();dexNames=Object.keys(d.pokemon||{});}catch{}}finally{dexIndexLoading=false;updateDexSuggestions();}}
function updateDexSuggestions(){const el=$('dexSuggestions');if(!el)return;const q=$('dexQuery')?.value||'';if(!q.trim()){el.innerHTML='<span class="muted tiny">Start typing to see matching Pokémon, including close spellings.</span>';return;}if(dexIndexLoading){el.innerHTML='<span class="muted tiny">Loading complete Pokédex names…</span>';return;}const matches=dexMatches(q);el.innerHTML=(dexIndexError?`<p class="muted tiny">${esc(dexIndexError)}</p>`:'')+(matches.length?matches.map(m=>`<button type="button" class="small ghost" data-action="dexSuggestion" data-name="${esc(m.name)}">${esc(pretty(m.name))}</button>`).join(' '):'<span class="muted tiny">No close matches yet. Try another spelling or Pokédex number.</span>');}
const inviteCode=(new URLSearchParams(location.search).get('room')||'').toUpperCase().replace(/[^A-Z2-9]/g,'').slice(0,6);
const sprite=(id,shiny=false)=>Number(id)>0?`https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/other/official-artwork/${shiny?'shiny/':''}${id}.png`:'';
function notify(message,bad=false){let t=$('toast');t.textContent=message;t.className=bad?'bad':'';t.style.display='block';clearTimeout(notify.t);notify.t=setTimeout(()=>t.style.display='none',5000)}
async function req(url,body){const cfg=body===undefined?{}:{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)};let r=await fetch(url,{...cfg,credentials:'same-origin'});let data=await r.json().catch(()=>({error:`Server error ${r.status}`}));if(!r.ok)throw new Error(data.error||`Server error ${r.status}`);return data;}
async function action(name,payload={}){try{const out=await req('/api/action',{action:name,payload});notify(out.message||'Saved');await refresh(true);return out;}catch(e){notify(e.message,true);return null}}
async function refresh(force=false){if(refreshBusy)return;refreshBusy=true;try{const next=await req('/api/session');if(!state||force||next.version!==state.version||next.role!==state.role||next.pending!==state.pending){state=next;render()}}catch(e){notify('Connection interrupted. Reconnecting to Avelora…',true)}finally{refreshBusy=false}}
function connectEvents(){if(es)es.close();if(!state?.signed_in)return;es=new EventSource('/api/events');es.addEventListener('version',ev=>{if(Number(ev.data)!==state?.version)refresh()});es.onerror=()=>{ /* EventSource auto-reconnects; periodic polling remains a fallback. */}}
function topIcon(ico){return `<span aria-hidden="true">${ico}</span>`}
function tab(label,key,ico){return `<button data-nav="${key}" class="${ui.tab===key?'active':''}">${topIcon(ico)} &nbsp; ${label}</button>`}
function layout(inner){const dm=state.role==='dm';const tabs=dm?[['Overview','overview','◈'],['Pokédex Builder','builder','⌕'],['All Pokémon','pokemon','◉'],['Battle Board','battle','⚔'],['Approvals ('+(state.requests||[]).length+')','approvals','✓'],['DM Tools','tools','⚙']]:[['My Pokémon','pokemon','◉'],['Battle','battle','⚔'],['Requests ('+(state.requests||[]).length+')','requests','⇄']];
return `<div class="page"><aside class="sidebar"><div class="logo"><div class="logo-badge">✦</div><div><h2>Avelora</h2><div class="eyebrow" style="font-size:9px">Combat Manager</div></div></div><nav class="nav" aria-label="Main navigation">${tabs.map(t=>tab(...t)).join('')}</nav><div class="sidebar-foot">◉ &nbsp; Avelora Online<br>Private campaign server<br><div class="padtop"><button class="small ghost" data-action="logout">Sign out</button></div></div></aside><main class="main"><div class="top"><div><div class="eyebrow">${dm?'Dungeon Master':'Trainer'} • ${esc(state.title||'Avelora')}</div><h1>${esc(dm?({'overview':'Command Center','builder':'Pokédex Builder','pokemon':'Pokémon Library','battle':'Battle Board','approvals':'Player Approvals','tools':'DM Tools'}[ui.tab]):({'pokemon':'My Pokémon','battle':'Live Battle','requests':'My Requests'}[ui.tab]))}</h1></div><span class="pill good">● Live Online</span></div>${inner}<div class="footer">Avelora Combat Manager · Online campaign · Server-validated turns and saves</div></main></div>`;}
function welcome(){return `<div class="login"><div class="login-inner"><div style="text-align:center;display:grid;gap:8px"><div class="brand-emblem">✦</div><div class="eyebrow">Echoes of Avelora</div><h1>Avelora Combat Manager</h1><p class="muted">Play from anywhere. One DM hosts the campaign and up to 10 Trainers join online.</p></div>${state.host_login?`<div class="card stack"><div class="eyebrow">DM access</div><h2>Dungeon Master</h2><p class="muted">Control the battle board, approve Trainers, and manage your campaign.</p><form class="stack" data-form="dmLogin"><div class="field"><label>DM password</label><input name="password" type="password" minlength="16" autocomplete="current-password" required placeholder="Your private DM password"></div><button class="primary">Enter DM Dashboard →</button></form></div>`:''}<div class="card stack"><div class="eyebrow">Player entrance</div><h2>Join a campaign</h2><p class="muted">Ask your DM for the six-character room code.</p><form class="stack" data-form="join"><div class="field"><label>Room code</label><input name="code" maxlength="6" required autocomplete="off" value="${esc(inviteCode)}" placeholder="Example: K7N4PX" style="text-transform:uppercase;letter-spacing:.14em"></div><div class="field"><label>Trainer nickname</label><input name="nickname" maxlength="28" minlength="2" required placeholder="Your Trainer's name"></div><button class="primary">Ask to Join →</button></form></div><p class="notice" style="text-align:center">Your DM must approve you before you can see your Pokémon. Keep this browser's cookies to remain signed in.</p></div></div>`;}
function pending(){return `<div class="login"><div class="login-inner"><div class="brand-emblem" style="text-align:center">⌛</div><div class="card stack"><div class="eyebrow">Waiting for the DM</div><h2>Welcome, ${esc(state.player.nickname)}!</h2><p class="muted">Your request was received. The DM needs to approve your Trainer.</p><div class="banner">This page automatically updates when you're approved.</div><div class="row"><button data-action="refresh">Refresh now</button><button data-action="logout" class="ghost">Leave room</button></div></div></div></div>`;}
function render(){if(!state){$('app').innerHTML='<div class="loading-screen">Loading…</div>';return}if(!state.signed_in){$('app').innerHTML=welcome();return}if(state.pending){$('app').innerHTML=pending();return}
if(state.role==='player'&&!['pokemon','battle','requests'].includes(ui.tab))ui.tab='pokemon';
let body='';if(state.role==='dm'){body=ui.tab==='overview'?overview():ui.tab==='builder'?builder():ui.tab==='pokemon'?pokemonList():ui.tab==='battle'?battleScreen():ui.tab==='approvals'?approvals():tools();}else{body=ui.tab==='pokemon'?pokemonList():ui.tab==='battle'?battleScreen():requests();}
$('app').innerHTML=layout(body);
if(state.role==='dm'&&ui.tab==='builder'){updateDexSuggestions();if(!dexIndexReady&&!dexIndexLoading)loadDexIndex();}
}
function players(){return state.players||[]}
function playerName(id){return (players().find(p=>p.id===id)?.nickname)||(id?'Trainer':'DM / Wild Pokémon')}
function shortName(p){return p.nickname||pretty(p.species)}
function statTags(p){let c=p.calculated||calcLocal(p);return `<div class="stats"><div class="stat"><span>Attack · STR ${c.strength}</span><strong>${sign(c.attack_mod)}</strong></div><div class="stat"><span>Physical AC · CON ${c.constitution}</span><strong>${c.physical_ac}</strong></div><div class="stat"><span>Sp. Attack · INT ${c.intelligence}</span><strong>${sign(c.special_mod)}</strong></div><div class="stat"><span>Special AC · WIS ${c.wisdom}</span><strong>${c.special_ac}</strong></div><div class="stat"><span>Initiative · DEX ${c.dexterity}</span><strong>${sign(c.speed_mod)}</strong></div><div class="stat"><span>Bond · CHA ${c.charisma}</span><strong>${sign(c.bond_mod)}</strong></div></div>`}
function calcLocal(p){let steps=Math.floor((p.level-1)/5),v=p.stats,scale=x=>clamp(8+Math.floor(x/8+.5)+steps,1,40),st=v.map(scale),cha=clamp(10+steps+clamp(p.bond_points||0,0,20),1,40),mod=x=>clamp(Math.floor((x-10)/4),-2,8),cap=p.legendary&&p.legend_ac?18:17,ac=x=>clamp(10+Math.floor((x-30)/14+.5),10,cap);return {max_hp:15+Math.floor(v[0]/8+.5)+steps*(4+Math.floor(v[0]/35+.5)),physical_ac:ac(v[2]),special_ac:ac(v[4]),strength:st[1],constitution:st[2],intelligence:st[3],wisdom:st[4],dexterity:st[5],charisma:cha,attack_mod:mod(st[1]),special_mod:mod(st[3]),speed_mod:mod(st[5]),bond_mod:mod(cha),to_hit:3+Math.floor((p.level-1)/25)};}
function bar(p){let max=p.calculated?.max_hp||calcLocal(p).max_hp,percent=100*clamp(p.current_hp||0,0,max)/Math.max(1,max);return `<div class="hpbar ${percent<35?'low':''}"><span style="width:${percent}%"></span></div><div class="muted tiny" style="margin-top:3px">HP ${p.current_hp}/${max}</div>`;}
function monCard(p,short=false){return `<div class="card mon-card" data-owner="${esc(p.owner||'dm')}"><div class="mon-head"><img src="${esc(sprite(p.dex_id,p.shiny))}" alt="" loading="lazy"><div class="stack" style="gap:4px"><h3 style="margin:0">${esc(shortName(p))} ${p.shiny?'<span style="color:var(--gold)">✧</span>':''}</h3><div class="muted smalltext">${esc(pretty(p.species))} · Lv ${p.level} · ${p.types.map(pretty).join(' / ')}</div><div class="row"><span class="pill">${p.slot==='party'?'Party':'Storage'}</span>${p.owner&&state.role==='dm'?`<span class="pill">${esc(playerName(p.owner))}</span>`:''}${p.legendary?'<span class="pill gold">Legendary</span>':''}</div></div></div>${bar(p)}${statTags(p)}<div class="tiny muted">${p.moves.map(m=>pretty(m.name)).join(' · ')||'No moves'} · EXP ${p.experience||0}</div><div class="row"><button class="small" data-action="viewMon" data-id="${esc(p.id)}">View &amp; Manage</button></div></div>`;}
function overview(){const ps=players(),pending=ps.filter(p=>p.state==='pending'),count=state.pokemon.length;return `<div class="stack"><div class="hero"><div class="eyebrow">Your online campaign</div><h2>Welcome back, Dungeon Master.</h2><p>Your private online server saves every Pokémon and synchronizes battle changes to your players in real time.</p><div class="row"><div><span class="muted tiny">PLAYER JOIN CODE</span><div class="bigcode">${esc(state.room_code)}</div></div><button class="small ghost" data-action="copyInvite">Copy player invite link</button><button class="small ghost" data-action="copyCode">Copy code</button><button class="primary" data-nav="battle">Open Battle Board →</button></div></div><div class="grid cols-3"><div class="card"><div class="eyebrow">Approved Trainers</div><h1>${ps.filter(p=>p.state==='approved').length} / 10</h1></div><div class="card"><div class="eyebrow">Saved Pokémon</div><h1>${count}</h1></div><div class="card"><div class="eyebrow">Battle</div><h2>${state.battle?pretty(state.battle.phase):'Not running'}</h2></div></div><div class="split"><div class="card stack"><h2>Trainer requests</h2>${pending.map(p=>`<div class="lineitem"><div><strong>${esc(p.nickname)}</strong><br><small>Waiting for approval</small></div><div class="row"><button class="small primary" data-action="approve" data-id="${p.id}">Approve</button><button class="small danger" data-action="removePlayer" data-id="${p.id}">Reject</button></div></div>`).join('')||'<p class="muted smalltext">No pending joins. Share the code with your players.</p>'}<div class="divider"></div><h3>Approved Trainers</h3>${ps.filter(p=>p.state==='approved').map(p=>`<div class="lineitem"><strong>${esc(p.nickname)}</strong><span class="pill good">Approved</span></div>`).join('')||'<p class="muted smalltext">No approved players yet.</p>'}</div><div class="card stack"><h2>Player change requests (${(state.requests||[]).length})</h2>${storageRequests(true)}<div class="divider"></div><h3>Quick start</h3><div class="row"><button data-nav="builder">+ Create Pokémon</button><button data-nav="battle">⚔ Start a battle</button></div><div class="warning">The room code allows joining requests only. Players receive personal access after DM approval, and hidden enemy information is filtered by the server.</div></div></div></div>`}
function monName(id){const p=(state.pokemon||[]).find(x=>x.id===id);return p?shortName(p):'Unknown Pokémon';}
function requestDescription(r){
 const kind=r.kind||'storage';
 if(kind==='moves'){const p=(state.pokemon||[]).find(x=>x.id===r.pokemon_id);return `Moves for <strong>${esc(monName(r.pokemon_id))}</strong><br><small>Current: ${esc((p?.moves||[]).map(m=>pretty(m.name)).join(', ')||'Unavailable')} → Proposed: ${esc((r.moves||[]).map(pretty).join(', '))}</small>`;}
 if(kind==='team'){const current=(state.pokemon||[]).filter(p=>p.owner===r.player_id && p.slot==='party').map(p=>shortName(p));return `New party (${(r.party_ids||[]).length}/6): ${esc((r.party_ids||[]).map(monName).join(', ')||'Empty party')}<br><small>Current: ${esc(current.join(', ')||'None')} · All other owned Pokémon go to storage.</small>`;}
 return `<strong>${esc(monName(r.pokemon_id))}</strong> → ${esc(r.slot==='party'?'Party':'Storage')}`;
}
function storageRequests(dm=false){const rs=state.requests||[];if(!rs.length)return '<p class="muted smalltext">No changes awaiting approval.</p>';
 return rs.map(r=>`<div class="lineitem"><div class="stack" style="gap:5px;flex:1"><div class="row"><span class="pill gold">${esc(pretty(r.kind||'storage'))}</span>${dm?`<strong>${esc(playerName(r.player_id))}</strong>`:''}<span class="muted tiny">${esc(r.when||'')}</span></div><div class="smalltext">${requestDescription(r)}</div></div>${dm?`<div class="row"><button class="small primary" data-action="storageAnswer" data-id="${r.id}" data-approve="true">✓ Approve</button><button class="small danger" data-action="storageAnswer" data-id="${r.id}" data-approve="false">✕ Deny</button></div>`:'<button class="small ghost" data-action="cancelRequest" data-id="${r.id}">Cancel</button>'}</div>`).join('');
}
function historyList(dm=false){const h=[...(state.change_history||[])].reverse().slice(0,20);if(!h.length)return '<p class="muted smalltext">No reviewed changes yet.</p>';
 return h.map(r=>`<div class="lineitem"><div class="stack" style="gap:4px;flex:1"><div class="row"><span class="pill ${r.status==='approved'?'good':'red'}">${r.status==='approved'?'Approved':'Denied'}</span><span class="pill">${esc(pretty(r.kind||'storage'))}</span>${dm?`<strong>${esc(playerName(r.player_id))}</strong>`:''}</div><div class="smalltext">${requestDescription(r)}</div>${r.reason?`<span class="muted tiny">DM note: ${esc(r.reason)}</span>`:''}</div><span class="muted tiny">${esc(r.decided_at||'')}</span></div>`).join('');
}
function approvals(){return `<div class="stack"><div class="hero"><div class="eyebrow">DM verification</div><h2>Approve player Pokémon changes</h2><p>Players can propose new legal moves, request full six-Pokémon party arrangements, or request single transfers. Nothing changes until you approve it. Battle actions still resolve normally.</p></div><div class="card stack"><h3>Waiting for your decision (${(state.requests||[]).length})</h3>${storageRequests(true)}</div><div class="card stack"><h3>Recent decisions</h3>${historyList(true)}</div></div>`;}
function requests(){const mons=state.pokemon||[], sorted=[...mons].sort((a,b)=>(a.slot==='party'?0:1)-(b.slot==='party'?0:1)||(a.party_order??99)-(b.party_order??99)||shortName(a).localeCompare(shortName(b)));
 return `<div class="stack"><div class="hero"><div class="eyebrow">DM-approved changes</div><h2>Manage your team</h2><p>Choose up to six Pokémon for your active party, including swaps from storage. Your DM will see the complete proposed team and can approve or deny it. Move changes are requested from each Pokémon’s sheet.</p></div><div class="card stack"><h3>Propose a party (maximum six)</h3><form data-form="teamRequest" class="stack"><div class="grid cols-2">${sorted.map(p=>`<label class="checkrow" style="border:1px solid var(--border);border-radius:10px;padding:12px;margin:0"><input type="checkbox" name="party_ids" value="${esc(p.id)}" ${p.slot==='party'?'checked':''}><span><strong>${esc(shortName(p))}</strong><br><span class="muted tiny">Lv ${p.level} · ${p.slot==='party'?'Current party':'Storage'}</span></span></label>`).join('')||'<p class="muted">Your DM has not assigned you any Pokémon yet.</p>'}</div><p class="notice">Unselected Pokémon will be in storage. The party changes only after DM approval. Existing combat is unaffected.</p><button class="primary" ${!mons.length?'disabled':''}>Send Team Change for DM Approval</button></form></div><div class="card stack"><h3>Pending requests (${(state.requests||[]).length})</h3>${storageRequests()}</div><div class="card stack"><h3>Recent decisions</h3>${historyList()}</div><button data-nav="pokemon">← Back to my Pokémon</button></div>`;
}
function pokemonList(){const arr=state.pokemon||[],mine=arr.filter(p=>p.slot==='party').sort((a,b)=>(a.party_order??99)-(b.party_order??99)), stored=arr.filter(p=>p.slot==='storage');if(ui.editor){const p=arr.find(x=>x.id===ui.editor);if(p)return pokemonDetail(p);ui.editor=null;}return `<div class="stack"><div class="hero"><div class="eyebrow">${state.role==='dm'?'Complete Pokédex collection':'Your Pokémon'}</div><h2>${arr.length} Pokémon saved</h2><p>${state.role==='dm'?'All Trainers, wild encounters, HP, levels, Bond, and shiny Pokémon are controlled here.':'Your party and storage update automatically while your DM runs the battle.'}</p>${state.role==='dm'?'<div><button class="primary" data-nav="builder">+ Add a Pokémon</button></div>':''}</div>${state.role==='dm'?`<div class="card"><label>Filter Pokémon</label><select id="filterOwner"><option value="">All ownership</option><option value="dm">DM / Wild</option>${players().filter(p=>p.state==='approved').map(p=>`<option value="${p.id}">${esc(p.nickname)}</option>`).join('')}</select></div>`:''}<div class="eyebrow">${state.role==='dm'?'Collection':'Party'} (${mine.length})</div><div class="mon-grid">${(state.role==='dm'?arr:mine).map(p=>monCard(p)).join('')||'<div class="card muted">No Pokémon yet. Ask your DM to create or assign your starter.</div>'}</div>${state.role==='player'?`<div class="eyebrow">Storage (${stored.length})</div><div class="mon-grid">${stored.map(p=>monCard(p)).join('')||'<div class="card muted">No Pokémon in storage.</div>'}</div>`:''}</div>`;}
function moveBadge(m){return `<span class="pill">${esc(pretty(m.name))} · ${esc(pretty(m.type))} · ${m.category==='status'?'Status':(m.power||'?')+' power'} · PP ${m.remaining_pp??m.pp}/${m.pp}</span>`;}
function pokemonDetail(p){let dm=state.role==='dm', legal=p.allowed_moves.filter(m=>m.learned_at<=p.level), known=new Set(p.moves.map(m=>m.name));return `<div class="stack"><div class="row between"><button data-action="closeMon">← Back to collection</button><span class="pill ${p.shiny?'gold':''}">${p.shiny?'✧ Shiny':'Standard'}</span></div><div class="split"><div class="stack"><div class="card stack"><div class="mon-head"><img src="${esc(sprite(p.dex_id,p.shiny))}" alt=""><div><h2>${esc(shortName(p))}</h2><p class="muted smalltext">${esc(pretty(p.species))} · Level ${p.level}</p></div></div>${bar(p)}${statTags(p)}<div class="row">${p.types.map(t=>`<span class="pill">${pretty(t)}</span>`).join('')}<span class="pill">${esc(pretty(p.ability))}</span></div><p class="muted smalltext">EXP ${p.experience||0} / ${p.level===100?'MAX':25+p.level*12+Math.floor(p.level/10)*20} · Bond points ${p.bond_points} · ${p.slot==='party'?'Party':'Storage'}</p>${p.move_learning_alert?'<div class="banner">New level-up moves are available below!</div>':''}${p.evolution_alert?'<div class="banner">Evolution may be available. Ask your DM to check the species requirements.</div>':''}</div><div class="card stack"><h3>Moves (choose up to four)</h3><p class="muted smalltext">${dm?'As DM, you can change these directly.':'Submit your chosen moves for DM approval. Your current moves remain usable until approved.'}</p><form data-form="saveMoves" class="stack"><input type="hidden" name="pokemon_id" value="${p.id}"><div class="grid cols-2">${legal.map(m=>`<label class="checkrow" style="border:1px solid var(--border);border-radius:9px;padding:8px;margin:0"><input type="checkbox" name="moves" value="${esc(m.name)}" ${known.has(m.name)?'checked':''}><span>${esc(pretty(m.name))}<br><span class="muted tiny">${esc(pretty(m.type))} · Lv ${m.learned_at} · ${m.power||'Status'}</span></span></label>`).join('')}</div><button class="primary">${dm?'Save Moves':'Request Move Change'}</button></form><p class="notice">Only level-up moves from the selected game version are auto-generated. The DM can handle special TM/tutor cases separately.</p></div></div><div class="stack"><div class="card stack"><h3>Nickname</h3><form data-form="nickname" class="row"><input type="hidden" name="id" value="${p.id}"><input name="nickname" maxlength="35" required value="${esc(p.nickname)}"><button>Save</button></form></div>${!dm?`<div class="card stack"><h3>Request party transfer</h3><p class="muted smalltext">Your DM must approve each transfer.</p><button data-action="storageRequest" data-id="${p.id}" data-slot="${p.slot==='party'?'storage':'party'}">Request move to ${p.slot==='party'?'storage':'party'}</button><button data-nav="requests">Plan full team swap →</button></div>`:`<div class="card stack"><h3>DM Pokémon Controls</h3><form class="stack" data-form="editPokemon"><input type="hidden" name="id" value="${p.id}"><div class="formgrid"><div><label>Trainer</label><select name="owner"><option value="dm" ${!p.owner?'selected':''}>DM / Wild</option>${players().filter(x=>x.state==='approved').map(x=>`<option value="${x.id}" ${p.owner===x.id?'selected':''}>${esc(x.nickname)}</option>`).join('')}</select></div><div><label>Level (1–100)</label><input name="level" type="number" min="1" max="100" value="${p.level}"></div><div><label>EXP toward next level</label><input name="experience" type="number" min="0" value="${p.experience||0}"></div><div><label>Current HP</label><input name="current_hp" type="number" min="0" max="${p.calculated.max_hp}" value="${p.current_hp}"></div><div><label>Status</label><select name="status">${['none','burn','poison','bad-poison','sleep','freeze','paralysis','confusion'].map(x=>`<option value="${x}" ${p.status===x?'selected':''}>${pretty(x)}</option>`).join('')}</select></div><div><label>Bond points (0–20)</label><input name="bond_points" type="number" min="0" max="20" value="${p.bond_points}"></div><div><label>Party / storage</label><select name="slot"><option value="party" ${p.slot==='party'?'selected':''}>Party</option><option value="storage" ${p.slot==='storage'?'selected':''}>Storage</option></select></div><div><label>Tera type</label><select name="tera_type">${types.map(t=>`<option value="${t}" ${t===p.tera_type?'selected':''}>${pretty(t)}</option>`).join('')}</select></div></div><label class="checkrow"><input type="checkbox" name="shiny" ${p.shiny?'checked':''}> Force shiny appearance</label><label class="checkrow"><input type="checkbox" name="legend_ac" ${p.legend_ac?'checked':''} ${p.legendary?'':'disabled'}> Legendary AC 18 allowed</label><label class="checkrow"><input type="checkbox" name="mega_enabled" ${p.mega_enabled?'checked':''}> Allow Mega Evolution</label><label class="checkrow"><input type="checkbox" name="tera_enabled" ${p.tera_enabled?'checked':''}> Allow Terastallization</label><button class="primary">Save DM Changes</button></form><form data-form="awardXp" class="row"><input type="hidden" name="id" value="${p.id}"><input type="number" name="amount" min="0" max="100000" placeholder="EXP to award" style="flex:1"><button>Grant EXP</button></form><div class="row"><button class="small" data-action="evolve" data-id="${p.id}">Evolve Pokémon...</button><button class="small danger" data-action="deletePokemon" data-id="${p.id}">Delete Pokémon</button></div></div>`}</div></div></div>`;}
function builder(){const ps=players().filter(p=>p.state==='approved');return `<div class="stack"><div class="hero"><div class="eyebrow">Official Pokémon + offline starters</div><h2>Create a wild Pokémon or Trainer partner</h2><p>Find Pokémon by partial name or close spelling. Set the creation level from 1–100; only moves learned by that level are randomized (up to four), and every creation has a 1-in-4,096 shiny roll. You can force a shiny manually.</p></div><div class="card stack"><div class="formgrid"><div><label>Search all Pokémon (misspellings supported)</label><input id="dexQuery" autocomplete="off" value="${esc(ui.dexQuery)}" placeholder="pikchu, shinx, ralts, 25..."><div id="dexSuggestions" class="row" style="flex-wrap:wrap;gap:6px;margin-top:8px" aria-live="polite"><span class="muted tiny">Type to see close matches.</span></div></div><div><label>Creation level (1–100)</label><input id="dexLevel" type="number" min="1" max="100" value="${ui.level}"></div></div><div class="row"><button class="primary" data-action="loadDex">Search Pokédex</button><span class="pill">Internet required for full Pokédex</span></div><div class="row"><span class="muted tiny">Quick offline picks:</span>${['larvitar','treecko','axew','shinx','gible','ralts','pidgey','sentret','bidoof','pikachu'].map(x=>`<button class="small ghost" data-action="offlinePick" data-name="${x}">${pretty(x)}</button>`).join('')}</div>${ui.searchBusy?'<div class="banner">Loading official Pokémon and level-up move data…</div>':''}${ui.dexError?`<div class="errorbox">${esc(ui.dexError)}</div>`:''}</div>${selected?`<div class="split"><div class="card stack"><div class="mon-head"><img src="${esc(sprite(selected.dex_id,ui.forceShiny))}" alt=""><div><h2>${esc(pretty(selected.species))}</h2><p class="muted smalltext">${selected.types.map(pretty).join(' / ')} · #${selected.dex_id} · ${esc(selected.version||'Offline')}</p></div></div>${statTags({...selected,level:ui.level,bond_points:0,legend_ac:ui.legendAC})}<div class="divider"></div><h3>Random legal moves</h3>${selected.allowed_moves.filter(m=>m.learned_at<=ui.level).slice(-35).map(m=>moveBadge(m)).join(' ')}<p class="notice">Actual moveset is randomly rolled when you click Create Pokémon. A newly created Pokémon gets a new shiny roll. If offline, available moves have approximate learn levels.</p></div><div class="card stack"><h3>Create ${esc(pretty(selected.species))}</h3><form class="stack" data-form="createPokemon"><div class="formgrid"><div><label>Nickname</label><input name="nickname" value="${esc(ui.nickname||pretty(selected.species))}" maxlength="35"></div><div><label>Assign to</label><select name="owner"><option value="">DM / Wild Pokémon</option>${ps.map(p=>`<option value="${p.id}">${esc(p.nickname)}</option>`).join('')}</select></div><div><label>Ability</label><select name="ability">${selected.abilities.map(a=>`<option value="${esc(a)}">${esc(pretty(a))}</option>`).join('')}</select></div><div><label>Tera type</label><select name="tera_type">${types.map(t=>`<option value="${t}" ${t===selected.types[0]?'selected':''}>${pretty(t)}</option>`).join('')}</select></div></div><label class="checkrow"><input type="checkbox" name="force_shiny"> Force Shiny ✧</label>${selected.legendary?'<label class="checkrow"><input type="checkbox" name="legend_ac"> DM-approved legendary AC 18 cap</label>':''}<label class="checkrow"><input type="checkbox" name="tera_enabled"> Permit Terastallization</label><label class="checkrow"><input type="checkbox" name="mega_enabled" ${selected.mega_forms.length?'':'disabled'}> Permit Mega Evolution ${selected.mega_forms.length?`(${selected.mega_forms.map(x=>pretty(x.name)).join(', ')})`:'— no eligible form found'}</label><button class="primary">Create Pokémon &amp; Roll Moves / Shiny</button></form></div></div>`:''}</div>`;}
function formattedDice(m,level){if(m.category==='status'||!m.power)return 'Status';return `${1+Math.floor((level-1)/20)}d${m.power<=30?4:m.power<=55?6:m.power<=80?8:m.power<=105?10:12}`}
function battleScreen(){let b=state.battle;if(!b)return state.role==='dm'?battleSetup():`<div class="hero"><div class="eyebrow">No battle yet</div><h2>Waiting for the DM</h2><p>When your DM sets up a battle, your team, initiative, and Pokémon actions will appear here automatically.</p></div>`;
if(b.phase==='finished')return `<div class="stack"><div class="hero"><div class="eyebrow">Battle complete</div><h2>The battle has ended.</h2><p>HP and PP are saved automatically in your online campaign. The DM can clear the board when everyone is ready.</p>${state.role==='dm'?'<button data-action="resetBattle">Clear battle board</button>':''}</div>${battleTeams(b)}${battleLog(b)}</div>`;
if(b.phase==='initiative')return initiativeScreen(b);
const actor=b.units.find(u=>u.id===b.order[b.turn_index]);const mine=actor&&(state.role==='dm'||actor.trainer_id===state.player.id);
return `<div class="stack"><div class="row between"><div class="featureline"><span class="pill good">Round ${b.round}</span><span class="pill">${esc(pretty(b.weather))} weather</span><span class="pill">${esc(pretty(b.terrain))} terrain</span><span class="pill gold">${actor?esc(shortName(actor))+'’s turn':'No current turn'}</span></div>${state.role==='dm'?'<div class="row"><button class="small" data-action="undo">↶ Undo</button><button class="small danger" data-action="endBattle">End Battle</button></div>':''}</div><div class="turnring" aria-label="Initiative order">${b.order.map((id,i)=>{let x=b.units.find(u=>u.id===id);return `<span class="pill ${i===b.turn_index?'good':''}">${i+1}. ${esc(shortName(x))}${!x.active?' [bench]':''}</span>`}).join('')}</div><div class="battlegrid"><section class="card stack"><h3>Trainer Team (${b.units.filter(x=>x.team==='ally').length})</h3><div class="team">${b.units.filter(x=>x.team==='ally').map(u=>unitHtml(u,actor?.id)).join('')}</div></section><section class="card actionpanel stack"><h2>Action Desk</h2>${actor&&mine?actionDesk(b,actor):`<div class="banner"><h3>${actor?esc(shortName(actor)):'Waiting for an active Pokémon'}</h3><p>${state.role==='dm'?'Open the current Pokémon’s action panel when the turn arrives.':'Waiting for another Trainer or the DM to finish their turn. This view updates in real time.'}</p></div>`}</section><section class="card stack"><h3>Opponents (${b.units.filter(x=>x.team==='enemy').length})</h3><div class="team">${b.units.filter(x=>x.team==='enemy').map(u=>unitHtml(u,actor?.id)).join('')}</div></section></div>${state.role==='dm'?dmBattleControls(b):''}${battleLog(b)}</div>`;
}
function unitHtml(u,current){const isOwner=!!u.stats,calc=isOwner?u.calculated||calcLocal(u):null;let hp=calc?`<div class="hpbar ${u.current_hp/calc.max_hp<.35?'low':''}"><span style="width:${100*clamp(u.current_hp/calc.max_hp,0,1)}%"></span></div><div class="tiny muted">HP ${u.current_hp}/${calc.max_hp} · AC ${calc.physical_ac}/${calc.special_ac}</div>`:`<span class="muted tiny">Health: ${esc(u.health||'Unknown')} · AC hidden</span>`;
return `<div class="unit ${u.id===current?'current':''} ${u.active?'':'bench'}"><img class="unit-icon" src="${esc(sprite(u.dex_id,u.shiny))}" alt="" loading="lazy"><div class="stack" style="gap:3px"><div class="row between"><strong class="smalltext">${esc(shortName(u))} ${u.shiny?'✧':''}</strong><span class="tiny muted">${u.active?'Active':'Bench'}${u.acted?' · Acted':''}</span></div>${hp}<div class="tiny muted">${esc(u.status&&u.status!=='none'?pretty(u.status):'OK')}${u.tera_active?' · Tera '+pretty(u.tera_type):''}${u.mega_active?' · Mega':''} · Init ${sign(u.initiative||0)}</div></div></div>`;}
function battleTeams(b){return `<div class="grid cols-2"><div class="card stack"><h3>Trainer Team</h3>${b.units.filter(u=>u.team==='ally').map(u=>unitHtml(u)).join('')}</div><div class="card stack"><h3>Opponents</h3>${b.units.filter(u=>u.team==='enemy').map(u=>unitHtml(u)).join('')}</div></div>`}
function battleLog(b){return `<div class="card stack"><h3>Combat Log</h3><div class="log">${(b.log||[]).slice().reverse().map(l=>`<div><span class="muted tiny">Round ${l.round}</span> &nbsp; ${esc(l.message)}</div>`).join('')||'<div>No actions yet.</div>'}</div></div>`}
function initiativeScreen(b){return `<div class="stack"><div class="hero"><div class="eyebrow">Battle preparation</div><h2>Roll Initiative</h2><p>Each Trainer rolls a physical d20, then the app adds their Pokémon's Speed modifier. The DM can enter NPC rolls. Unentered rolls use a passive 10.</p>${state.role==='dm'?'<button class="primary" data-action="beginBattle">Begin Combat →</button>':''}</div><div class="grid cols-2"><div class="card stack"><h3>Player Pokémon</h3>${b.units.filter(u=>u.team==='ally').map(u=>initiativeInput(u)).join('')}</div><div class="card stack"><h3>Enemy Pokémon</h3>${b.units.filter(u=>u.team==='enemy').map(u=>initiativeInput(u)).join('')}</div></div></div>`;}
function initiativeInput(u){let can=state.role==='dm'||u.trainer_id===state.player?.id;let speed=u.calculated?.speed_mod??(u.stats?calcLocal(u).speed_mod:null);return `<div class="lineitem"><div><strong>${esc(shortName(u))}</strong><br><small>${can?`Speed ${sign(speed)} · `:''}Total ${u.initiative??10}</small></div>${can?`<form data-form="initiative" class="row"><input name="unit_id" type="hidden" value="${u.id}"><input name="roll" type="number" min="1" max="20" placeholder="d20" aria-label="Initiative die for ${esc(shortName(u))}" style="width:80px"><button class="small">Set</button></form>`:'<span class="pill">Waiting</span>'}</div>`;}
function battleSetup(){const p=state.pokemon||[],ps=players();const sorted=p.filter(x=>x.current_hp>0),choose=(team)=>sorted.map(mon=>{let selected=(team==='ally'?ui.setupAllies:ui.setupEnemies).includes(mon.id);return `<label class="lineitem checkrow" style="margin:0"><span><strong>${esc(shortName(mon))} · Lv ${mon.level}</strong><br><small>${esc(playerName(mon.owner))} · HP ${mon.current_hp}</small></span><input type="checkbox" data-team="${team}" value="${mon.id}" ${selected?'checked':''}></label>`}).join('');return `<div class="stack"><div class="hero"><div class="eyebrow">Battle setup</div><h2>Create a new battle</h2><p>Build any matchup from 1v1 to 20v20, including uneven rosters. Choose active slots; the rest are reserves. Turn order is based on physical initiative rolls.</p><button data-nav="builder">+ Add Pokémon in Pokédex</button></div><div class="grid cols-2"><div class="card stack"><h3>Trainer side · ${ui.setupAllies.length} selected</h3><div class="scrollbox stack">${choose('ally')||'<p class="muted">Create Pokémon first.</p>'}</div></div><div class="card stack"><h3>Opponent side · ${ui.setupEnemies.length} selected</h3><div class="scrollbox stack">${choose('enemy')||'<p class="muted">Create Pokémon first.</p>'}</div></div></div><div class="card stack"><h3>Active slots</h3><form data-form="startBattle" class="stack"><div class="formgrid"><div><label>Simultaneously active Trainers</label><input type="number" name="ally_slots" min="1" max="20" value="${Math.max(1,Math.min(ui.setupAllies.length,3))}"></div><div><label>Simultaneously active opponents</label><input type="number" name="enemy_slots" min="1" max="20" value="${Math.max(1,Math.min(ui.setupEnemies.length,3))}"></div></div><button class="primary" ${!ui.setupAllies.length||!ui.setupEnemies.length?'disabled':''}>Create Battle → Initiative</button></form></div></div>`;}
function actionDesk(b,a){if(a.current_hp<=0)return '<div class="banner">This Pokémon has fainted. DM may activate a healthy reserve.</div>';
const c=a.calculated||calcLocal(a);let m=a.moves?.[ui.battleMove]||a.moves?.[0], mi=a.moves?.indexOf(m)||0;if(!m)return '<p class="errorbox">No moves set. DM must fix this Pokémon.</p>';
const other=b.units.filter(u=>u.active&&(typeof u.current_hp==='number'?u.current_hp>0:u.health!=='Fainted')&&u.id!==a.id);
const targetKind={'earthquake':'all-other-pokemon','surf':'all-other-pokemon','discharge':'all-other-pokemon','bulldoze':'all-other-pokemon','explosion':'all-other-pokemon','rock-slide':'all-opponents','razor-leaf':'all-opponents','heat-wave':'all-opponents','swift':'all-opponents'}[m.name]||m.target||'selected-pokemon';
let self=m.category==='status'&&['user','users-field','user-and-allies','user-or-ally'].includes(targetKind);
let area=['all-other-pokemon','entire-field','all-opponents','all-opposing-pokemon'].includes(targetKind);
let targets=area?other.filter(u=>targetKind.includes('opponent')?u.team!==a.team:true):self?[a]:other.filter(u=>m.category==='status'||u.team!==a.team);
if(!ui.battleTarget||!targets.find(t=>t.id===ui.battleTarget))ui.battleTarget=targets[0]?.id||a.id;
let actualTargets=area?targets:targets.filter(t=>t.id===ui.battleTarget);
const dice=formattedDice(m,a.level),auto=m.accuracy==null,accuracyAdjustment=m.accuracy==null?0:clamp(Math.floor((m.accuracy-100)/10+.5),-6,0),tohit=c.to_hit+accuracyAdjustment+(a.stages?.accuracy||0);
const mods=m.category==='physical'?c.attack_mod:m.category==='special'?c.special_mod:0;
const healOrStatus=m.category==='status',reserve=b.units.filter(u=>u.team===a.team&&u.trainer_id===a.trainer_id&&!u.active&&u.current_hp>0);
const used=b.used_transformations?.[a.trainer_id||'dm-'+a.team]||{};
return `<div class="stack"><div class="mon-head"><img src="${esc(sprite(a.dex_id,a.shiny))}" alt=""><div><h3 style="margin:0">${esc(shortName(a))}</h3><div class="muted smalltext">Level ${a.level} · ${a.types.map(pretty).join(' / ')}</div><span class="pill">${a.status&&a.status!=='none'?pretty(a.status):'Ready'}</span></div></div>${statTags({...a,calculated:c})}<div class="divider"></div><h3>1 · Select a move</h3><div class="action-row">${a.moves.map((v,i)=>`<button class="move ${mi===i?'selected':''}" data-action="chooseMove" data-index="${i}" ${v.remaining_pp<=0?'disabled':''}><strong>${esc(pretty(v.name))}</strong><span class="tiny muted">${pretty(v.type)} · ${pretty(v.category)} · ${v.remaining_pp}/${v.pp} PP</span></button>`).join('')}</div><div class="dice-hint"><strong>${esc(pretty(m.name))}</strong> — ${esc(pretty(m.type))}, ${esc(pretty(m.category))}<br>${healOrStatus?'Status effect':`Damage dice ${dice} ${sign(mods)} stat bonus`} · ${auto?'Always hits / self':`d20 ${sign(tohit)} to hit`} · ${m.power??'—'} power<br>${esc(m.effect||'Special effects may need DM adjudication.')}<br><span class="tiny">${area?'Area attack — roll separately for each target. Friendly fire may apply.':''} AC: ${m.category==='physical'?'Physical':m.category==='special'?'Special':'Status move'}.</span></div><h3>2 · Target and physical dice</h3>${!area&&!self?`<div class="field"><label>Choose target</label><select id="targetSelect">${targets.map(t=>`<option value="${t.id}" ${ui.battleTarget===t.id?'selected':''}>${esc(shortName(t))} ${state.role==='dm'?'· AC '+defensePreview(t,m.category):''}</option>`).join('')}</select></div>`:''}<form data-form="attack" class="stack"><input name="move_index" type="hidden" value="${mi}">${actualTargets.map(t=>`<div class="target-roll"><div class="target-name"><strong class="smalltext">${esc(shortName(t))}</strong><br><small>${esc(t.team===a.team?'Ally / self':'Opponent')} · ${state.role==='dm'?'Target AC '+defensePreview(t,m.category):'Enemy AC hidden'}</small><input name="target_id" type="hidden" value="${t.id}"></div><div><label>d20 roll</label><input class="dice-d20" type="number" min="1" max="20" placeholder="${auto?'Auto':'1–20'}" ${auto?'disabled':''}></div><div><label>Dice sum</label><input class="dice-sum" type="number" min="0" placeholder="${healOrStatus?'—':'Total'}" ${healOrStatus?'disabled':''}></div>${c.charisma>=26&&!a.bond_reroll_used&&!auto?'<div style="grid-column:1/-1"><label>Optional high-Bond d20 reroll (once per battle)</label><input class="dice-reroll" type="number" min="1" max="20" placeholder="Second d20 only if used"></div>':''}</div>`).join('')}<div class="notice">Enter the sum of the damage dice only; the host adds STR/INT, type, STAB, statuses, and other modifiers. On natural 20 roll double dice. Leave damage empty on misses.</div><div class="row"><button class="primary" ${actualTargets.length?'':'disabled'}>Resolve Move</button><button type="button" data-action="passTurn">Pass Turn</button></div></form>${reserve.length?`<div class="divider"></div><h3>Switch Pokémon (uses turn)</h3><div class="row"><select id="reserveChoice" style="flex:1">${reserve.map(r=>`<option value="${r.id}">${esc(shortName(r))} · Lv ${r.level}</option>`).join('')}</select><button data-action="switch">Switch</button></div>`:''}${(a.mega_enabled||a.tera_enabled)?`<div class="divider"></div><h3>DM-approved Transformations</h3><div class="row">${a.mega_enabled&&!a.mega_active&&!a.tera_active&&!used.mega&&a.mega_forms?.length?`<select id="megaForm" style="flex:1">${a.mega_forms.map(m=>`<option value="${esc(m.name)}">${esc(pretty(m.name))}</option>`).join('')}</select><button data-action="mega">Mega Evolve</button>`:''}${a.tera_enabled&&!a.mega_active&&!a.tera_active&&!used.tera?`<button data-action="tera">Terastallize (${esc(pretty(a.tera_type))})</button>`:''}</div>`:''}</div>`;
}
function defensePreview(u,category){if(!u.stats)return '?';let c=u.calculated||calcLocal(u),base=c[category==='physical'?'physical_ac':'special_ac'],key=category==='physical'?'defense':'special-defense';return clamp(base+Math.floor((u.stages?.[key]||0)/2+.5)+(u.temp_ac?.[category]||0),5,22);}
function dmBattleControls(b){return `<div class="grid cols-2"><div class="card stack"><h3>DM Overrides</h3><p class="muted smalltext">Use this for special move effects, corrections, healing, temporary AC, and initiative changes. Every override appears in the log.</p><form data-form="override" class="stack"><div class="formgrid"><div><label>Combatant</label><select name="unit_id">${b.units.map(u=>`<option value="${u.id}">${esc(shortName(u))} · ${pretty(u.team)}</option>`).join('')}</select></div><div><label>Change</label><select name="kind"><option value="hp">Set HP</option><option value="damage">Inflict flat damage</option><option value="heal">Heal HP</option><option value="status">Status (none, burn, poison…)</option><option value="physical">Temporary Physical AC</option><option value="special">Temporary Special AC</option><option value="attack">Attack stage</option><option value="defense">Defense stage</option><option value="special-attack">Sp. Attack stage</option><option value="special-defense">Sp. Defense stage</option><option value="speed">Speed stage</option><option value="accuracy">Accuracy stage</option><option value="initiative">Set initiative total</option><option value="active">Activate / bench (true / false)</option></select></div><div><label>New value</label><input name="value" placeholder="e.g. 10, -1, burn"></div><div><label>Turns (0 = until changed)</label><input type="number" name="duration" min="0" max="99" value="0"></div></div><button>Apply Override</button></form></div><div class="card stack"><h3>Battlefield</h3><form data-form="weather" class="stack"><div class="formgrid"><div><label>Weather</label><select name="weather">${weather.map(x=>`<option value="${x}" ${x===b.weather?'selected':''}>${pretty(x)}</option>`).join('')}</select></div><div><label>Terrain</label><select name="terrain">${terrain.map(x=>`<option value="${x}" ${x===b.terrain?'selected':''}>${pretty(x)}</option>`).join('')}</select></div></div><button>Update Weather & Terrain</button></form><div class="divider"></div><button class="danger" data-action="endBattle">End battle and save progress</button><p class="muted smalltext">Temporary AC may exceed the usual base cap during battle. Natural AC still tops out at 17, or 18 for approved legendaries.</p></div></div>`}
function dmRestPanel(){const mons=state.pokemon||[],trainers=players().filter(p=>p.state==='approved'),history=(state.rest_history||[]).slice(-8).reverse();return `<div class="card stack"><h3>DM · Short & Long Rest</h3><p class="muted smalltext">Healing scales with the Pokémon's level AND the percentage of HP missing: 1 die per 20% of maximum HP lost (1–5 dice). Die size increases with level: d4 / d6 / d8 / d10 / d12. Resting never revives a Pokémon at 0 HP. End battles before resting.</p><form data-form="dmRest" class="stack"><div class="formgrid"><div><label>Rest type</label><select name="kind" id="restKind"><option value="short">Short Rest · missing-HP healing dice</option><option value="long">Long Rest · extra healing dice</option></select></div><div><label>Who rests?</label><select name="scope" id="restScope"><option value="pokemon">One Pokémon</option><option value="trainer">Trainer's Pokémon (party + storage)</option><option value="everyone">Everyone (including DM / wild)</option></select></div><div id="restPokemonField"><label>Pokémon</label><select name="pokemon_id">${mons.map(p=>`<option value="${esc(p.id)}">${esc(shortName(p))} · Lv ${p.level} · ${esc(playerName(p.owner))}</option>`).join('')}</select></div><div id="restTrainerField" style="display:none"><label>Trainer</label><select name="trainer_id"><option value="dm">DM / Wild Pokémon</option>${trainers.map(t=>`<option value="${esc(t.id)}">${esc(t.nickname)}</option>`).join('')}</select></div></div><div id="longRestOptions" class="stack" style="display:none"><div class="notice">Long Rest uses twice as many healing dice as Short Rest by default, scaling with level and missing HP. The DM can increase the multiplier and optionally restore PP or clear ordinary status conditions.</div><label>Long Rest dice multiplier (2–10; default 2×)</label><input name="dice_multiplier" type="number" min="2" max="10" value="2"><label class="checkrow"><input name="restore_pp" type="checkbox"> Restore move PP</label><label class="checkrow"><input name="clear_status" type="checkbox"> Clear ordinary status conditions</label></div><button class="primary" ${mons.length?'':'disabled'}>Apply Rest</button></form>${history.length?`<div class="divider"></div><h4>Recent rests</h4>${history.map(h=>`<div class="lineitem"><div><strong>${esc(pretty(h.kind))} Rest</strong> · ${esc(h.when)}<br><small>${h.results.length} Pokémon · ${h.results.reduce((sum,r)=>sum+r.healed,0)} HP healed · ${esc(h.results.map(r=>`${r.pokemon} ${r.dice}: +${r.healed}`).join(' · ').slice(0,260))}</small></div></div>`).join('')}`:''}</div>`;}
function tools(){return `<div class="stack">${dmRestPanel()}<div class="hero"><h2>DM Settings & Backups</h2><p>All campaign data is automatically saved to the server's persistent SQLite volume. Export backup files regularly for safekeeping.</p><div class="row"><button data-action="backup">Create SQLite backup now</button><a href="/api/backup.json" class="pill" download>Export full campaign JSON</a></div></div><div class="card stack"><h3>Private online room</h3><div class="bigcode">${esc(state.room_code)}</div><p class="muted">Up to 10 approved Trainers can join. Share the website address and room code only with your players. Keep the DM password private.</p><h3>Trainers</h3>${players().map(p=>`<div class="lineitem"><div><strong>${esc(p.nickname)}</strong><br><small>${p.state}</small></div><button class="small danger" data-action="removePlayer" data-id="${p.id}">Remove</button></div>`).join('')||'<p class="muted">No Trainers yet.</p>'}</div><div class="notice">Your web host provides HTTPS. The DM password, join approvals, and server-side permissions protect your room. Download campaign backups occasionally, especially before upgrading.</div><div class="card"><h3>Rules in this edition</h3><p class="muted smalltext">Natural AC depends on species and evolution, capped at 17 (18 for permitted legendaries). HP and offensive stats scale every five levels. Physical dice rolls, four moves, types, STAB, EXP, shiny generation, Bond, Mega/Tera controls, switching, and 1v1–20v20 matchups are supported. Many unusual Pokémon abilities, intricate moves, and special evolution conditions require DM adjudication.</p></div></div>`;}
const moveCache=new Map();
async function pokeMove(name){if(moveCache.has(name))return moveCache.get(name);const r=await fetch('https://pokeapi.co/api/v2/move/'+encodeURIComponent(name));if(!r.ok)throw new Error('Move lookup failed for '+name);let d=await r.json(),eff=d.effect_entries?.find(x=>x.language.name==='en')?.short_effect?.replaceAll('$effect_chance',String(d.effect_chance||0))||'';
let result={name:d.name,type:d.type.name,category:d.damage_class.name,power:d.power,accuracy:d.accuracy,pp:d.pp||15,target:d.target?.name||'selected-pokemon',effect:eff.slice(0,200),ailment:d.meta?.ailment?.name||'none',ailment_chance:d.meta?.ailment_chance||0,stat_changes:(d.stat_changes||[]).map(a=>({stat:a.stat.name,change:a.change}))};moveCache.set(name,result);return result;}
async function ensureOffline(){if(!offline)offline=await req('/api/offline');return offline;}
async function loadOffline(name,lv){let d=await ensureOffline();name=name.toLowerCase();let x=d.pokemon[name];if(!x)throw new Error('Offline Pokédex has starter and Route 1 Pokémon only. Use online search for '+name+'.');const pool=x.moves.map((n,i)=>{let r=d.moves[n]||[40,100,'physical'];return {name:n,type:d.move_types[n]||'normal',power:r[0],accuracy:r[1],category:r[2],pp:15,learned_at:i<3?1:Math.min(100,5+i*5),target:'selected-pokemon',effect:'Offline approximation; DM can adjudicate effects.',ailment:r[3]||'none',ailment_chance:r[4]||0}});
return {dex_id:x.id,species:name,stats:x.stats,types:x.types,abilities:x.abilities,legendary:Boolean(x.legendary),allowed_moves:pool,mega_forms:[],version:'Offline approximate learnset',offline:true};}
async function loadSpecies(q,lvl,forceOffline=false){const raw=String(q).toLowerCase().trim().replace(/\s+/g,'-');if(forceOffline)return loadOffline(raw,lvl);
try{const resp=await fetch('https://pokeapi.co/api/v2/pokemon/'+encodeURIComponent(raw));if(!resp.ok)throw new Error('Pokémon not found');const p=await resp.json();let species=null;try{let sr=await fetch(p.species.url);if(sr.ok)species=await sr.json()}catch{}
const entries=p.moves||[],versions=new Set(entries.flatMap(e=>e.version_group_details.filter(v=>v.move_learn_method.name==='level-up').map(v=>v.version_group.name)));
const group=preferredVersions.find(v=>versions.has(v))||[...versions][0]||'';
let rawLegal=entries.map(e=>({name:e.move.name,learned_at:e.version_group_details.find(v=>v.version_group.name===group&&v.move_learn_method.name==='level-up')?.level_learned_at})).filter(x=>x.learned_at!==undefined).sort((a,b)=>a.learned_at-b.learned_at);
if(rawLegal.length>120)rawLegal=[...rawLegal.slice(0,30),...rawLegal.slice(-90)];
let details=[];for(let i=0;i<rawLegal.length;i+=12){const chunk=await Promise.allSettled(rawLegal.slice(i,i+12).map(async v=>({...await pokeMove(v.name),learned_at:v.learned_at})));details.push(...chunk.filter(x=>x.status==='fulfilled').map(x=>x.value));}
if(!details.length)throw new Error('No level-up move data for that Pokémon at this level');
const megaNames=(species?.varieties||[]).map(v=>v.pokemon.name).filter(n=>n.includes('-mega'));
const megaForms=[];for(const n of megaNames.slice(0,4)){
try{const r=await fetch('https://pokeapi.co/api/v2/pokemon/'+encodeURIComponent(n));if(r.ok){const m=await r.json();megaForms.push({name:m.name,dex_id:m.id,stats:['hp','attack','defense','special-attack','special-defense','speed'].map(t=>m.stats.find(y=>y.stat.name===t)?.base_stat||50),types:m.types.sort((a,b)=>a.slot-b.slot).map(x=>x.type.name),ability:m.abilities?.[0]?.ability?.name})}}catch{}
}
return {dex_id:p.id,species:p.name,stats:['hp','attack','defense','special-attack','special-defense','speed'].map(x=>p.stats.find(y=>y.stat.name===x)?.base_stat||50),types:p.types.sort((a,b)=>a.slot-b.slot).map(t=>t.type.name),abilities:p.abilities.map(a=>a.ability.name),legendary:Boolean(species?.is_legendary||species?.is_mythical),allowed_moves:details,mega_forms:megaForms,version:group,offline:false};
}catch(e){const d=await ensureOffline();if(d.pokemon[raw]){notify('Online Pokédex unavailable. Showing approximate offline data.');return loadOffline(raw,lvl)}throw e;}
}
async function selectDex(q,lv,offlineOnly){if(!q)return notify('Enter a Pokémon name or number',true);ui.dexQuery=q;ui.level=clamp(Number(lv)||5,1,100);ui.searchBusy=true;ui.dexError='';selected=null;render();try{selected=await loadSpecies(q,ui.level,offlineOnly);ui.nickname=pretty(selected.species);ui.dexError='';ui.teraType=selected.types[0];}catch(e){ui.dexError=e.message||String(e)}finally{ui.searchBusy=false;render()}}
function formObj(form){return Object.fromEntries(new FormData(form).entries());}
async function onForm(form){let name=form.dataset.form,d=formObj(form);
try{
if(name==='dmLogin'){await req('/api/host_login',{password:d.password});ui.tab='overview';await refresh(true);connectEvents();return;}
switch(name){
case 'join':await req('/api/join',d);await refresh(true);connectEvents();return;
case 'createPokemon':{
 if(!selected)throw new Error('Select a Pokémon first');
 let mon={...selected,owner:d.owner||null,level:ui.level,nickname:d.nickname,ability:d.ability,tera_type:d.tera_type,force_shiny:!!form.querySelector('[name=force_shiny]:checked'),legend_ac:!!form.querySelector('[name=legend_ac]:checked'),tera_enabled:!!form.querySelector('[name=tera_enabled]:checked'),mega_enabled:!!form.querySelector('[name=mega_enabled]:checked')};
 let out=await action('create_pokemon',{pokemon:mon});if(out){ui.tab='pokemon';ui.editor=out.pokemon_id;render()}return;}
case 'saveMoves':{const chosen=[...form.querySelectorAll('input[name=moves]:checked')].map(x=>x.value);await action(state.role==='dm'?'player_moves':'request_moves',{id:d.pokemon_id,moves:chosen});return;}
case 'teamRequest':{const chosen=[...form.querySelectorAll('input[name=party_ids]:checked')].map(x=>x.value);if(chosen.length>6)throw new Error('A party can contain only six Pokémon');await action('request_team',{party_ids:chosen});return;}
case 'nickname':await action(state.role==='dm'?'edit_pokemon':'player_nickname',d);return;
case 'awardXp':await action('dm_award_xp',{id:d.id,amount:Number(d.amount)});return;
case 'editPokemon':{
let p={...d,owner:d.owner==='dm'?null:d.owner,level:Number(d.level),experience:Number(d.experience),bond_points:Number(d.bond_points),current_hp:Number(d.current_hp),status:d.status,shiny:!!form.querySelector('[name=shiny]:checked'),legend_ac:!!form.querySelector('[name=legend_ac]:checked'),mega_enabled:!!form.querySelector('[name=mega_enabled]:checked'),tera_enabled:!!form.querySelector('[name=tera_enabled]:checked')};await action('edit_pokemon',p);return;}
case 'dmRest':{const target_id=d.scope==='pokemon'?d.pokemon_id:d.scope==='trainer'?d.trainer_id:null;if(!confirm(`Apply ${d.kind} rest to ${d.scope==='everyone'?'every Pokémon':d.scope==='trainer'?'this Trainer’s Pokémon':'the selected Pokémon'}?`))return;await action('dm_rest',{kind:d.kind,scope:d.scope,target_id,dice_multiplier:Number(d.dice_multiplier||1),restore_pp:!!form.querySelector('[name=restore_pp]:checked'),clear_status:!!form.querySelector('[name=clear_status]:checked')});return;}
case 'startBattle':await action('start_battle',{allies:ui.setupAllies,enemies:ui.setupEnemies,ally_slots:Number(d.ally_slots),enemy_slots:Number(d.enemy_slots)});return;
case 'initiative':await action(state.role==='dm'?'dm_initiative':'player_initiative',{unit_id:d.unit_id,roll:Number(d.roll)});return;
case 'attack':{
let moveIndex=Number(d.move_index),rows=[...form.querySelectorAll('.target-roll')],targets=rows.map(row=>({target_id:row.querySelector('[name=target_id]').value,d20:row.querySelector('.dice-d20').disabled?null:row.querySelector('.dice-d20').value,dice_sum:row.querySelector('.dice-sum').disabled||row.querySelector('.dice-sum').value===''?0:row.querySelector('.dice-sum').value,reroll_d20:row.querySelector('.dice-reroll')?.value||null}));
let out=await action('attack',{move_index:moveIndex,targets});if(out){ui.battleMove=0;ui.battleTarget=null}return;}
case 'override':await action('dm_override',{unit_id:d.unit_id,kind:d.kind,value:d.value,duration:Number(d.duration)});return;
case 'weather':await action('dm_weather',d);return;
}
}catch(e){notify(e.message,true)}
}
async function onClick(btn){let actionName=btn.dataset.action,id=btn.dataset.id;
switch(actionName){
case 'hostLogin':return notify('Use the DM password form above.',true);
case 'refresh':return refresh(true);
case 'logout':if(confirm('Sign out of this device? A player who signs out will need DM approval to join again.')){await req('/api/logout',{});if(es)es.close();ui.tab='overview';state=null;return refresh(true)}return;
case 'copyInvite':{let link=new URL('/',location.origin);link.searchParams.set('room',state.room_code);try{await navigator.clipboard.writeText(link.href);notify('Player invite link copied!')}catch(e){prompt('Copy this player invite link:',link.href)}return;}
case 'copyCode':navigator.clipboard?.writeText(state.room_code).then(()=>notify('Room code copied')).catch(()=>notify('Room code: '+state.room_code));return;
case 'approve':await action('approve_player',{id});return;
case 'removePlayer':if(confirm('Remove this Trainer? Players with Pokémon cannot be removed until their Pokémon are reassigned.'))await action('remove_player',{id});return;
case 'storageAnswer':{const approve=btn.dataset.approve==='true';let reason='';if(!approve){const entered=prompt('Optional reason for denying this request (Cancel to keep pending):','');if(entered===null)return;reason=entered;}await action('review_change',{id,approve,reason});return;}
case 'storageRequest':await action('request_storage',{id,slot:btn.dataset.slot});return;
case 'cancelRequest':await action('cancel_request',{id});return;
case 'viewMon':ui.editor=id;render();return;
case 'closeMon':ui.editor=null;render();return;
case 'dexSuggestion':return selectDex(btn.dataset.name,$('dexLevel')?.value||ui.level,false);
case 'offlinePick':return selectDex(btn.dataset.name,$('dexLevel')?.value||ui.level,true);
case 'loadDex':return selectDex($('dexQuery')?.value||'', $('dexLevel')?.value||5,false);
case 'deletePokemon':if(confirm('Delete this Pokémon permanently? This cannot be undone.')){let out=await action('delete_pokemon',{id});if(out){ui.editor=null;render()}}return;
case 'evolve':{
const p=state.pokemon.find(x=>x.id===id);let next=prompt(`Evolution for ${p?.nickname||'Pokémon'} — enter the exact new species name (DM approves requirements):`);if(!next)return;
try{let info=await loadSpecies(next,p.level);let out=await action('evolve_pokemon',{id,new_form:{...info,level:p.level}});if(out)ui.editor=id;}catch(e){notify(e.message,true)}return;}
case 'beginBattle':return action('begin_battle');
case 'endBattle':if(confirm('End this battle and sync HP and PP?'))return action('end_battle');return;
case 'resetBattle':if(confirm('Clear finished battle? All saved Pokémon remain.')){ui.setupAllies=[];ui.setupEnemies=[];return action('reset_battle')}return;
case 'undo':return action('undo');
case 'chooseMove':ui.battleMove=Number(btn.dataset.index);ui.battleTarget=null;render();return;
case 'passTurn':return action('pass');
case 'switch':return action('switch',{reserve_id:$('reserveChoice')?.value});
case 'mega':return action('transform',{mode:'mega',form:$('megaForm')?.value});
case 'tera':return action('transform',{mode:'tera'});
case 'backup':return action('backup');
}
}
document.addEventListener('click',ev=>{const nav=ev.target.closest('[data-nav]');if(nav){ui.tab=nav.dataset.nav;ui.editor=null;ui.battleMove=0;ui.battleTarget=null;render();return;}const btn=ev.target.closest('[data-action]');if(btn){ev.preventDefault();onClick(btn).catch(e=>notify(e.message,true));}});
document.addEventListener('submit',ev=>{let f=ev.target.closest('[data-form]');if(!f)return;ev.preventDefault();onForm(f).catch(e=>notify(e.message,true))});
document.addEventListener('change',ev=>{let tar=ev.target;if(tar.matches('[data-team]')){let key=tar.dataset.team==='ally'?'setupAllies':'setupEnemies',other=tar.dataset.team==='ally'?'setupEnemies':'setupAllies';if(tar.checked){ui[key]=[...new Set([...ui[key],tar.value])];ui[other]=ui[other].filter(x=>x!==tar.value)}else ui[key]=ui[key].filter(x=>x!==tar.value);render();return}if(tar.id==='restScope'||tar.id==='restKind'){const scope=$('restScope')?.value;const kind=$('restKind')?.value;if($('restPokemonField'))$('restPokemonField').style.display=scope==='pokemon'?'':'none';if($('restTrainerField'))$('restTrainerField').style.display=scope==='trainer'?'':'none';if($('longRestOptions'))$('longRestOptions').style.display=kind==='long'?'':'none';return}if(tar.id==='targetSelect'){ui.battleTarget=tar.value;render();return}if(tar.id==='dexLevel'){ui.level=clamp(Number(tar.value)||5,1,100);render();return}if(tar.id==='filterOwner'){const val=tar.value;document.querySelectorAll('.mon-card').forEach(c=>{c.style.display=(!val||c.dataset.owner===val)?'':'none'})}});
document.addEventListener('input',ev=>{if(ev.target.id==='dexQuery'){ui.dexQuery=ev.target.value;updateDexSuggestions();}});
document.addEventListener('focusin',ev=>{if(ev.target.id==='dexQuery'&&!dexIndexReady&&!dexIndexLoading)loadDexIndex();});
window.addEventListener('DOMContentLoaded',async()=>{await refresh(true);connectEvents();setInterval(()=>refresh(),9000)});
